// Generated by Cypress Author — 2026-10-01
describe('Documentation', () => {
    beforeEach(() => {
        cy.login()
    })

    it('Footer link → opens functional documentation and follows an internal link', () => {
        cy.visit('/')
        cy.get('footer').contains('a', 'Documentation').click()

        cy.url().should('include', '/documentation/specs/INDEX.md')
        cy.get('.documentation-content h1').should('contain', 'Spécifications fonctionnelles')
        cy.get('.documentation-sidebar a[aria-current="page"]').should('contain', 'Spécifications fonctionnelles')

        cy.get('.documentation-content').contains('a', 'MOD-01 — Établissements').click()

        cy.url().should('include', '/documentation/specs/MOD-01-ETABLISSEMENTS.md')
        cy.get('.documentation-content h1').should('contain', 'Établissements')
    })

    it('Tech subfolder document → renders with the active navigation item and isolated HTML access', () => {
        cy.visit('/documentation/tech/dossier/edition-dossiers.md')

        cy.get('.documentation-content h1').should('exist')
        cy.get('.documentation-sidebar a[aria-current="page"]')
            .should('have.attr', 'href')
            .and('include', '/documentation/tech/dossier/edition-dossiers.md')

        cy.request('/documentation/tech/toast-demo.html').then((response) => {
            expect(response.status).to.equal(200)
            expect(response.headers['content-type']).to.include('text/html')
            expect(response.headers['content-security-policy']).to.include('sandbox')
            expect(response.body).to.include('<!DOCTYPE html>')
            expect(response.body).to.include('Démo - Notifications Toast')
        })
    })

    // Generated by Cypress Author — 2026-10-02
    const viewportWidths = [320, 375, 1280]
    viewportWidths.forEach((width) => {
        it(`Read documentation at ${width}px → long texts stay within their containers`, () => {
            cy.viewport(width, 800)
            cy.visit('/documentation/specs/INDEX.md')
            cy.get('.documentation-content h1').should('contain', 'Spécifications fonctionnelles')

            // Exercise unbroken identifiers, non-breaking hyphens and diagram separators.
            cy.document().then((document) => {
                const longText = 'Documentation\u2011'.repeat(20)
                document.querySelector('.documentation-sidebar a[aria-current="page"]').textContent = longText
                document.querySelector('.documentation-breadcrumb .active').textContent = longText

                const fixture = document.createElement('div')
                fixture.innerHTML = '<p></p><p><code></code></p><pre><code></code></pre>'
                    + '<table><thead><tr><th>Identifiant</th><th>Description</th><th>Exemple</th></tr></thead>'
                    + '<tbody><tr><td></td><td></td><td><code></code></td></tr></tbody></table>'
                fixture.querySelector('p').textContent = longText
                fixture.querySelector('p code').textContent = longText
                fixture.querySelector('pre code').textContent = '\u2500'.repeat(200)
                fixture.querySelectorAll('td').forEach((cell) => {
                    (cell.querySelector('code') || cell).textContent = longText
                })
                document.querySelector('.documentation-content').append(fixture)
            })

            cy.document().should((document) => {
                const viewportWidth = document.documentElement.clientWidth
                expect(document.documentElement.scrollWidth, 'page width').to.be.at.most(viewportWidth)

                document.querySelectorAll(
                    '.documentation-sidebar, .documentation-breadcrumb, .documentation-content, '
                    + '.documentation-content pre, .documentation-content table'
                ).forEach((element) => {
                    expect(element.scrollWidth, `${element.tagName} content width`)
                        .to.be.at.most(element.clientWidth + 1)
                    expect(element.getBoundingClientRect().right, `${element.tagName} right edge`)
                        .to.be.at.most(viewportWidth + 1)
                })
            })
        })
    })
})
